  return [{
    name:'format_value',
    description:'Format a value according to its kind.',
    inputSchema:{
      type:'object',
      properties:{
        value:{type:'string'},
        kind:{type:'string',enum:['text','integer']}
      },
      required:['value','kind'],
      additionalProperties:false
